/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * The panel: an ST7789V-family controller on SPI1 (HW-27 to HW-32).
 * Commands go out a byte at a time; pixels go out by DMA straight from the
 * frame buffer, in chunks that SPI1's interrupt chains, so the core is
 * free while a frame is on its way (docs/DESIGN-NOTES.md, M2).
 */

#include "sb.h"
#include "WL82.h"

/* HW-29: CON bit 15 reads 1 when a transfer is done, writing bit 14
 * clears that, bit 13 makes a finished transfer raise source 16. */
#define SPI_DONE  (1u << 15)
#define SPI_CLEAR (1u << 14)
#define SPI_IRQ   (1u << 13)

/* SPI1's own set-up (clock, mode, pins) on the chip is open (Q-6, SR-3);
 * fwtest needs none (HW-29). These are the CON bits that set-up will
 * keep in every write; none yet. */
#define SPI_CON   0u

/* HW-30: PC8 low for a command byte, high for its parameters and for
 * pixels. Only that bit of the port is ever changed. */
#define LCD_DC    (1u << 8)

/* DS (HW-31, HW-32): the commands used. */
#define SWRESET   0x01u
#define SLPOUT    0x11u
#define CASET     0x2Au
#define RASET     0x2Bu
#define RAMWR     0x2Cu
#define MADCTL    0x36u
#define COLMOD    0x3Au

/* Bytes a DMA transfer sends at most: 16 rows. E-5 (HW-29) confirms
 * 480-byte transfers; how long one may be on the chip is asked in SR-3,
 * so a whole frame goes as 15 of these. */
#define ROW_BYTES (SCREEN_W * 2u)
#define CHUNK     (16u * ROW_BYTES)

/* A frame on its way: the next byte to send and how many are left, set
 * by lcd_send_rows and moved on by lcd_spi_done. */
static const u8 *volatile dma_next;
static volatile u32 dma_left;
/* 1 while a transfer started without the interrupt may still be going. */
static volatile u32 dma_polled;
static u32 frame_start;

static void dc_low(void)  { JL_PORTC->OUT &= ~LCD_DC; }
static void dc_high(void) { JL_PORTC->OUT |= LCD_DC; }

static void send_byte(u32 b)
{
    JL_SPI1->BUF = b;
    while (!(JL_SPI1->CON & SPI_DONE))
        ;
    JL_SPI1->CON = SPI_CON | SPI_CLEAR;
}

/* Waits until no transfer is on its way, so the data/command line may
 * change (HW-30: its level when a transfer starts decides it). A chained
 * frame ends in lcd_spi_done. This spins rather than idling: the last
 * chunk's interrupt could come between the test and an idle, which would
 * then sleep until the next tick (it did, once a frame, in the flood
 * test). Only a command that follows a frame still going out waits. */
void lcd_wait(void)
{
    while (dma_left)
        ;
    if (dma_polled) {
        while (dma_polled && !(JL_SPI1->CON & SPI_DONE))
            ;
        JL_SPI1->CON = SPI_CON | SPI_CLEAR;
        dma_polled = 0;
    }
}

void lcd_command(u8 command, const u8 *params, u32 count)
{
    lcd_wait();
    dc_low();
    send_byte(command);
    dc_high();
    while (count--)
        send_byte(*params++);
}

static void start_chunk(void)
{
    u32 n = dma_left < CHUNK ? dma_left : CHUNK;

    JL_SPI1->ADR = (u32)dma_next;
    dma_next += n;
    sb_beacon.chunks++;
    JL_SPI1->CNT = n;
}

/* Source 16: a chunk is done. Send the next, or end the frame. fwtest
 * also raises source 16 at the end of a transfer started with bit 13
 * clear (our experiment, P-20; HW-29 says bit 13 enables it; SR-3): with
 * no chain under way that is the polled transfer ending, so it is only
 * acknowledged, and lcd_wait sees it is over. */
void lcd_spi_done(void)
{
    u32 n = dma_left < CHUNK ? dma_left : CHUNK;

    if (!n) {
        JL_SPI1->CON = SPI_CON | SPI_CLEAR;
        dma_polled = 0;
        return;
    }
    dma_left -= n;
    if (dma_left) {
        JL_SPI1->CON = SPI_CON | SPI_CLEAR | SPI_IRQ;
        start_chunk();
    } else {
        JL_SPI1->CON = SPI_CON | SPI_CLEAR;
        sb_beacon.frame_ticks = sb_now() - frame_start;
        sb_beacon.frames++;
    }
}

/* Sends rows first to first + rows - 1 of the frame buffer to the same
 * rows of the panel (HW-31: column and row address set, then memory
 * write, high byte first; sb_fb holds each pixel that way round). Up to
 * one chunk goes as one transfer whose end is polled by the next
 * lcd_wait; more go as a chain of chunks driven by source 16. Returns
 * once the last transfer has started. */
void lcd_send_rows(u32 first, u32 rows)
{
    u32 last = first + rows - 1, bytes = rows * ROW_BYTES;
    u8 cols[4] = { 0, 0, (SCREEN_W - 1) >> 8, (SCREEN_W - 1) & 0xFF };
    u8 lines[4] = { first >> 8, first & 0xFF, last >> 8, last & 0xFF };

    frame_start = sb_now();
    lcd_command(CASET, cols, 4);
    lcd_command(RASET, lines, 4);
    lcd_command(RAMWR, 0, 0);
    dma_next = (const u8 *)&sb_fb[first * SCREEN_W];
    if (bytes <= CHUNK) {
        dma_polled = 1;
        JL_SPI1->CON = SPI_CON | SPI_CLEAR;
        JL_SPI1->ADR = (u32)dma_next;
        sb_beacon.chunks++;
        JL_SPI1->CNT = bytes;
        return;
    }
    dma_left = bytes;
    JL_SPI1->CON = SPI_CON | SPI_CLEAR | SPI_IRQ;
    start_chunk();
}

/* The controller's start: a software reset, sleep out, 16-bit pixels, and
 * the scan order. The display stays off until the first frame is in
 * (main sends DISPON). Delays from HW-32 and DS pages 163 and 184, each
 * waited on the tick, so they hold on the chip too. */
void lcd_init(void)
{
    /* DS page 215: MY = MX = MV = 0 (rows top to bottom, columns left to
     * right, not exchanged), ML = 0, RGB order (bit 3 clear), MH = 0. */
    static const u8 madctl = 0x00;
    /* DS page 224: 0x55, 65K colours and 16 bits a pixel. */
    static const u8 colmod = 0x55;

    lcd_command(SWRESET, 0, 0);
    /* 5 ms before the next command; 120 ms before sleep out when the
     * reset came in sleep mode, which it does after power-up. */
    sb_wait_ms(120);
    lcd_command(SLPOUT, 0, 0);
    sb_wait_ms(5);
    lcd_command(COLMOD, &colmod, 1);
    lcd_command(MADCTL, &madctl, 1);
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * The live panel screen (M3): every control's state, drawn from the input
 * layer's events, with each button's and key's LED lit while it is held,
 * so the whole panel can be tried by hand. It replaces the test screen at
 * the first event (docs/DESIGN-NOTES.md, M3, "The panel screen"), and
 * each event then redraws only what it changed and sends only those rows.
 * tools/fw-suite.py checks it against golden images; the layout here and
 * the goldens go together.
 */

#include "sb.h"
#include "input.h"

#define BLACK   RGB565(0, 0, 0)
#define WHITE   RGB565(31, 63, 31)
#define DARK    RGB565(6, 12, 6)
#define GREY    RGB565(12, 24, 12)
#define YELLOW  RGB565(31, 63, 0)
#define ORANGE  RGB565(31, 40, 0)
#define CYAN    RGB565(0, 63, 31)

/* Buttons: 36 x 13 boxes. */
#define BUTTON_W 36u
#define BUTTON_H 13u
/* Knobs: two rows of four cells, 57 pixels wide, name then value. */
#define KNOB_W   57u
#define BAR_Y    122u
#define BAR_W    232u
/* The keyboard: 16 lower keys 13 pixels wide every 14, raised keys 9
 * wide over the gaps. */
#define KEYS_Y   132u
#define LOWER_H  52u
#define RAISED_H 30u
#define EVENT_Y  190u

static const char button_names[14][5] = {
    "OCT-", "OCT+", "FX", "SEL", "ENV", "LFO", "EDIT", "GLO",
    "HOME", "SAVE", "ARP", "SEQ", "PLAY", "REC",
};
/* Knobs in screen order, and their names. */
static const u8 knob_order[8] = {
    INPUT_SELECT, INPUT_PRESETS, INPUT_ALGORITHM, INPUT_MASTER,
    INPUT_KNOB1, INPUT_KNOB2, INPUT_KNOB3, INPUT_KNOB4,
};
static const char knob_names[8][10] = {
    "MASTER", "SELECT", "PRESETS", "ALGORITHM", "KNOB1", "KNOB2", "KNOB3", "KNOB4",
};
/* KEY1 to KEY27 from left to right: a lower key's number (0 to 15), or
 * 0x80 | the lower key a raised key follows (HW-36: raised keys in groups
 * of 3, 2, 3, 2, 1). */
static const u8 key_shape[27] = {
    0, 0x80, 1, 0x81, 2, 0x82, 3, 4, 0x84, 5, 0x85, 6, 7, 0x87,
    8, 0x88, 9, 0x89, 10, 11, 0x8B, 12, 0x8C, 13, 14, 0x8E, 15,
};
static const char *const kind_names[5] = { "", "press", "release", "turn", "move" };

static u32 shown;

static void button_place(u32 id, u32 *x, u32 *y)
{
    if (id < 2) {
        *x = 6 + id * 38;
        *y = 50;
    } else {
        *x = 6 + (id - 2) % 6 * 38;
        *y = 18 + (id - 2) / 6 * 16;
    }
}

static u32 length(const char *s)
{
    u32 n = 0;

    while (s[n])
        n++;
    return n;
}

/* Writes v in decimal at b, with a + for positive values when sign is
 * set; returns the characters written (at most 7). */
static u32 decimal(char *b, int v, int sign)
{
    char d[8];
    u32 n = 0, i = 0, u = (u32)(v < 0 ? -v : v);

    if (v < 0)
        b[i++] = '-';
    else if (v > 0 && sign)
        b[i++] = '+';
    do {
        d[n++] = (char)('0' + u % 10);
        u /= 10;
    } while (u && n < 6);
    while (n)
        b[i++] = d[--n];
    return i;
}

static void draw_button(u32 id)
{
    u32 x, y, down = (u32)input_value(id);
    const char *name = button_names[id];

    button_place(id, &x, &y);
    gfx_fill(x, y, BUTTON_W, BUTTON_H, down ? YELLOW : DARK);
    gfx_text(x + (BUTTON_W - length(name) * FONT_CELL) / 2, y + 3, name,
             down ? BLACK : WHITE, down ? YELLOW : DARK, 1);
}

/* The knob in screen place i (0 to 7): its value, and for MASTER the bar
 * below the knobs; returns the value's first row. */
static u32 draw_knob(u32 i)
{
    u32 id = knob_order[i], x = 4 + i % 4 * 59, y = 80 + i / 4 * 26, n;
    int v = input_value(id);
    char b[10];

    n = decimal(b, v, id != INPUT_MASTER);
    while (n < 9)
        b[n++] = ' ';
    b[9] = 0;
    gfx_text(x, y, b, id == INPUT_MASTER ? CYAN : YELLOW, BLACK, 1);
    if (id == INPUT_MASTER) {
        u32 w = (u32)v * BAR_W / 1023;
        gfx_fill(4, BAR_Y, w, 6, CYAN);
        gfx_fill(4 + w, BAR_Y, BAR_W - w, 6, DARK);
    }
    return y;
}

static void draw_keys(void)
{
    u32 k, pass;

    gfx_fill(0, KEYS_Y, SCREEN_W, LOWER_H, BLACK);
    /* Lower keys first, then the raised keys over them. */
    for (pass = 0; pass < 2; pass++) {
        for (k = 0; k < 27; k++) {
            u32 s = key_shape[k], down = (u32)input_value(INPUT_KEY1 + k);
            if (!(s & 0x80) && !pass)
                gfx_fill(8 + 14 * s, KEYS_Y, 13, LOWER_H, down ? ORANGE : WHITE);
            else if ((s & 0x80) && pass)
                gfx_fill(8 + 14 * ((s & 0x7F) + 1) - 5, KEYS_Y, 9, RAISED_H, down ? ORANGE : GREY);
        }
    }
}

/* "<control> <kind> <value>" for the last event. */
static void draw_event(const struct input_event *e)
{
    char b[41];
    const char *name;
    u32 n = 0, i;

    if (e->control < 14) {
        name = button_names[e->control];
    } else if (e->control < INPUT_MASTER) {
        name = "KEY";
    } else {
        name = knob_names[e->control - INPUT_MASTER];
    }
    for (i = 0; name[i]; i++)
        b[n++] = name[i];
    if (e->control >= INPUT_KEY1 && e->control <= INPUT_KEY27)
        n += decimal(&b[n], (int)(e->control - INPUT_KEY1 + 1), 0);
    b[n++] = ' ';
    for (i = 0; kind_names[e->kind < 5 ? e->kind : 0][i]; i++)
        b[n++] = kind_names[e->kind][i];
    if (e->kind == INPUT_TURN || e->kind == INPUT_MOVE) {
        b[n++] = ' ';
        n += decimal(&b[n], e->value, e->kind == INPUT_TURN);
    }
    while (n < 38)
        b[n++] = ' ';
    b[n] = 0;
    gfx_text(4, EVENT_Y, b, WHITE, BLACK, 1);
}

static void draw_all(void)
{
    u32 i;

    gfx_fill(0, 0, SCREEN_W, SCREEN_H, BLACK);
    gfx_text(4, 4, "small-beeps M3 panel", WHITE, BLACK, 1);
    for (i = 0; i < 14; i++)
        draw_button(i);
    for (i = 0; i < 8; i++) {
        gfx_text(4 + i % 4 * 59, 70 + i / 4 * 26, knob_names[knob_order[i] - INPUT_MASTER], WHITE, BLACK, 1);
        draw_knob(i);
    }
    draw_keys();
    screen_beat_all();
}

/* Takes every queued event: its LED first (so it changes with the least
 * delay), then the screen. */
void panel_serve(void)
{
    struct input_event e;

    while (input_read(&e)) {
        if (e.control < INPUT_LEDS)
            input_led(e.control, e.kind == INPUT_PRESS ? INPUT_LED_FULL : 0);
        if (!shown) {
            shown = 1;
            draw_all();
            draw_event(&e);
            lcd_send_rows(0, SCREEN_H);
            sb_beacon.screen = SB_SCREEN_PANEL;
            continue;
        }
        if (e.control < 14) {
            u32 x, y;
            draw_button(e.control);
            button_place(e.control, &x, &y);
            lcd_send_rows(y, BUTTON_H);
        } else if (e.control < INPUT_MASTER) {
            draw_keys();
            lcd_send_rows(KEYS_Y, LOWER_H);
        } else {
            u32 i = 0, y;
            while (knob_order[i] != e.control)
                i++;
            y = draw_knob(i);
            lcd_send_rows(y, FONT_H);
            if (e.control == INPUT_MASTER)
                lcd_send_rows(BAR_Y, 6);
        }
        draw_event(&e);
        lcd_send_rows(EVENT_Y, FONT_H);
    }
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Test builds only. tools/perf.py builds the firmware with each of
 * SB_PROBE_SLOW, SB_PROBE_BIG and SB_PROBE_STACK defined, and checks that
 * the performance gates fail the first two and that the stack's high-water
 * mark sees the third (R-PERF-3, R-PERF-5). tools/fw-suite.py builds it
 * with each of SB_TEST_FAULT, SB_TEST_STRAY and SB_TEST_BADINSN, which go
 * wrong on purpose once interrupts are on (R-IRQ-3, R-IRQ-4), and with
 * SB_TEST_FLOOD, which keeps the panel busy (R-LCD-5), SB_TEST_LEDS,
 * which sets every LED to its own brightness (R-LED-2), and
 * SB_TEST_LED_SHOW, whose scan times when it first drives an LED just set
 * (input.c; R-LED-3). The firmware itself
 * is built with none, and then nothing here is compiled.
 */

#include "sb.h"
#include "input.h"
#include "WL82.h"

#if defined(SB_PROBE_STACK)
static volatile u32 probe_sink;
#endif

#if defined(SB_PROBE_SLOW)
/* Extra work on every heartbeat beat: the speed gate must catch it. */
void sb_probe_slow(void)
{
    volatile u32 i;

    for (i = 0; i < 20; i++)
        ;
}
#endif

#if defined(SB_PROBE_BIG)
/* More code (a 1 KiB table among the constants), more static RAM (256
 * bytes of zeroed data) and a deeper stack (512 bytes, every word written
 * with a non-zero value): each budget must catch its own. */
static const u32 probe_table[256] = { 1 };
static volatile u32 probe_ram[64];

static void __attribute__((noinline)) probe_stack(void)
{
    volatile u32 frame[128];
    u32 i;

    for (i = 0; i < 128; i++)
        frame[i] = i + 1;
    probe_ram[0] = frame[127];
}

void sb_probe_big(void)
{
    probe_stack();
    probe_ram[1] = probe_table[sb_beacon.beats & 255];
}
#endif

#if defined(SB_PROBE_STACK)
/* A known amount of stack: a 1 KiB frame, written with zeros (which RAM
 * already holds in fwtest, so only the fill pattern can show them) and
 * read back. The high-water mark must be at least 1024 bytes. */
static void __attribute__((noinline)) probe_zero_frame(void)
{
    volatile u32 frame[256];
    u32 i, sum = 0;

    for (i = 0; i < 256; i++)
        frame[i] = 0;
    for (i = 0; i < 256; i++)
        sum += frame[i];
    probe_sink = sum;
}

void sb_probe_stack(void)
{
    probe_zero_frame();
}
#endif

#if defined(SB_TEST_FAULT)
/* Overruns main's stack: a frame as big as the whole stack, written, so
 * the stack's guard word is overwritten. The next tick must find it and
 * halt with "HALT stack 001". */
static volatile u32 test_sink;

static void __attribute__((noinline)) test_overrun(void)
{
    volatile u32 frame[512];
    u32 i;

    _Static_assert(sizeof frame >= 0x800, "the frame covers main's whole stack");
    for (i = 0; i < 512; i++)
        frame[i] = i;
    test_sink = frame[0];
}

void sb_test_fault(void)
{
    test_overrun();
}
#endif

#if defined(SB_TEST_STRAY)
/* An interrupt nothing handles: software interrupt 7 (source 127, HW-19),
 * enabled (HW-20) and raised (HW-23). It must halt with "HALT stray 07f". */
void sb_test_stray(void)
{
    (&q32DSP(0)->ICFG00)[127 / 8] = (1u | 1u << 1) << 4 * (127 % 8);
    q32DSP(0)->ILAT_SET = 1u << 7;
}
#endif

#if defined(SB_TEST_BADINSN)
/* An instruction the emulated CPU cannot decode. fwtest stops the run with
 * its own fault outcome before any handler of ours runs: a limit of the
 * harness, not something the firmware reports (SR-1). */
void sb_test_badinsn(void)
{
    __asm__ volatile(".short 0xffff\n\t.short 0xffff");
}
#endif

#if defined(SB_TEST_FLOOD)
/* Whole frames back to back, for ever, once the test screen is up: every
 * tick of the run comes while a frame is being sent or set up, and must
 * keep its timing (R-LCD-5). Core 0 never waits here, so fwtest's
 * captures are exact. */
void sb_test_flood(void)
{
    for (;;) {
        lcd_send_rows(0, SCREEN_H);
        lcd_wait();
    }
}
#endif

#if defined(SB_TEST_LEDS)
/* Every LED at its own brightness: LED n at (n mod 9) eighths of full,
 * as levels 0 to 255 round them (input.h), so each of the 9 steps shows
 * on several LEDs and every LED on some step. */
void sb_test_leds(void)
{
    u32 n;

    for (n = 0; n < INPUT_LEDS; n++)
        input_led(n, n % 9 * INPUT_LED_FULL / 8);
}
#endif
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * The image's first instruction. Core 0 starts here with every register
 * but r0 at zero and no usable stack (HW-1, HW-2), so this sets the stack
 * pointers and hands over to C. Also what C can't write: sb_stack_fill
 * (it needs the stack pointer), sb_clock_measure (it needs an exact
 * instruction count), and the interrupt stubs (they need the address they
 * were called from).
 */

	.section .text.entry,"ax",@progbits
	.globl	_start
	.type	_start,@function
_start:
	/* r0 holds the loader's block pointer (HW-4); M1 doesn't use it. */
	r1 = __stack_top
	sp = r1
	/* Core 0 runs in user mode, and an interrupt switches to ssp (HW-3,
	 * confirmed by our own run: docs/DESIGN-NOTES.md, M1), so ssp must
	 * be valid before interrupts are enabled. */
	r1 = __irq_stack_top
	ssp = r1
	/* Before any C, so every use of either stack shows (R-PERF-3). */
	call	sb_stack_fill
	call	sb_start

	/* sb_start never returns. If it ever did, stop on purpose: interrupts
	 * off and a jump to itself, which fwtest reports as a halt. */
	cli
.Lstop:
	goto	.Lstop
	.size	_start, .-_start

/* Fills the unused stack area, from its limit up to the current sp, with
 * SB_STACK_FILL, so a test can see how deep each stack ever went: the
 * lowest word no longer holding the pattern (tools/perf.py, R-PERF-3).
 * The area holds both stacks, so this fills the interrupt stack whole,
 * and the lowest word of each stack is left holding the pattern as its
 * guard (sb_tick checks both). _start calls it before anything else,
 * so nothing has used either stack yet. A leaf: a call keeps its return
 * address in rets, so nothing below sp is in use. */
	.set	SB_STACK_FILL, 0x4B415453	/* "STAK"; also in sb.h */

	.text
	.globl	sb_stack_fill
	.type	sb_stack_fill,@function
sb_stack_fill:
	r0 = __stack_limit
	r1 = sp + 0
	r2 = SB_STACK_FILL
	if (r0 >= r1) goto .Lfilled
.Lfill:
	[r0++=4] = r2
	if (r0 < r1) goto .Lfill
.Lfilled:
	rts
	.size	sb_stack_fill, .-sb_stack_fill

/* Measures the core clock against the 24 MHz time base (HW-13): reads
 * TIMER4's count (its address in r0, from C), runs exactly
 * SB_CLOCK_CYCLES instructions, reads it again and returns the difference. fwtest runs one instruction a cycle
 * (HW-11), so at 240 MHz the result is SB_CLOCK_CYCLES / 10, give or take
 * one for where in a count the reads fall. The two reads are far apart,
 * so fwtest never treats this as waiting (docs/HARNESS.md, "Time"). */
	.set	SB_CLOCK_LOOPS, 1200		/* 2 instructions each */

	.globl	sb_clock_measure
	.type	sb_clock_measure,@function
sb_clock_measure:
	r2 = [r0+0]
	r3 = SB_CLOCK_LOOPS
.Lspin:
	r3 += -1
	if (r3 != 0) goto .Lspin
	r1 = [r0+0]
	r0 = r1 - r2
	rts
	.size	sb_clock_measure, .-sb_clock_measure

/* One stub per interrupt source, 2 bytes each (the short form of call,
 * which reaches sb_irq_stub_common from every stub; app.ld asserts the
 * size), in source order: every
 * slot of the vector table that has no handler of its own points at its
 * source's stub (firmware/src/irq.c). A stub calls sb_irq_stub_common,
 * which works out the source from the stub's address (the return address
 * in rets) and halts with a report. Nothing returns, so clobbering rets
 * and the scratch registers is fine. */
	.p2align 1
	.globl	sb_irq_stubs, sb_irq_stubs_end
	.type	sb_irq_stubs,@function
sb_irq_stubs:
	.rept	128
	call	sb_irq_stub_common
	.endr
sb_irq_stubs_end:
	.size	sb_irq_stubs, .-sb_irq_stubs

	.type	sb_irq_stub_common,@function
sb_irq_stub_common:
	cli
	r0 = rets
	r1 = sb_irq_stubs + 2
	r0 = r0 - r1
	r0 >>= 1				/* the source number */
	r1 = reti				/* where the interrupt came in */
	call	sb_irq_unexpected
.Lnever:
	goto	.Lnever
	.size	sb_irq_stub_common, .-sb_irq_stub_common
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Memory layout for the raw image (docs/DESIGN-NOTES.md, M0d).
 *
 * IMAGE: the code window. The image's first byte is at its start and is
 *   the first instruction run (HW-1); the window shows the flash chip from
 *   offset 0x4000, so an image may be up to 1 MiB less 16 KiB (HW-5).
 * RAM: main RAM is 512 KiB from 0x01C00000 on the chip (HW-6). Its top,
 *   from 0x01C7FC00, is not part of RAM here: the block r0 points to at
 *   entry (HW-4) and the SDK's boot and update area are left alone, and
 *   the vector table at 0x01C7FE00 (HW-18) is written only by
 *   firmware/src/irq.c, through __vectors. fwtest has more RAM (HW-7);
 *   this layout uses only what the chip has.
 * The stack area is two stacks (HW-3): main's, on sp, at the top, and the
 *   interrupt stack, on ssp, below it. Each one's lowest word is its guard
 *   (docs/DESIGN-NOTES.md, M1).
 */

OUTPUT_ARCH(pi32v2)
ENTRY(_start)

MEMORY
{
    IMAGE (rx)  : ORIGIN = 0x02000000, LENGTH = 0x000FC000
    RAM   (rwx) : ORIGIN = 0x01C00000, LENGTH = 0x0007FC00
}

STACK_SIZE = 0x1000;          /* both stacks */
IRQ_STACK_SIZE = 0x800;       /* the lower half: interrupts, on ssp */

SECTIONS
{
    .text : {
        KEEP(*(.text.entry))
        *(.text .text.*)
        *(.rodata .rodata.*)
        . = ALIGN(4);
    } > IMAGE

    /* Fixed at the start of RAM so the tests know where it is: the
     * beacon, then (since M3) the input record. */
    .beacon (NOLOAD) : {
        __bss_start = .;
        KEEP(*(.beacon))
        KEEP(*(.beacon.input))
    } > RAM

    .bss (NOLOAD) : {
        *(.bss .bss.*)
        . = ALIGN(4);
        __bss_end = .;
    } > RAM

    /* Runs from RAM, loaded from the image just after the code. */
    .data : {
        __data_start = .;
        *(.data .data.*)
        . = ALIGN(4);
        __data_end = .;
    } > RAM AT > IMAGE
    __data_load = LOADADDR(.data);

    /* The stack takes the top of RAM and grows down from __stack_top. */
    __stack_top = ORIGIN(RAM) + LENGTH(RAM);
    __stack_limit = __stack_top - STACK_SIZE;
    __irq_stack_top = __stack_limit + IRQ_STACK_SIZE;
    __vectors = 0x01C7FE00;

    ASSERT(ADDR(.beacon) == 0x01C00000, "the beacon must start main RAM")
    ASSERT(sb_input == 0x01C00060, "the input record must follow the beacon (M3)")
    ASSERT(__data_end <= __stack_limit, "data and bss run into the stack")
    ASSERT(__stack_top == 0x01C7FC00, "the stack must end below the reserved top of RAM")
    ASSERT(__stack_top % 8 == 0, "the stack must be 8-byte aligned")
    ASSERT(__irq_stack_top % 8 == 0, "the interrupt stack must be 8-byte aligned")
    ASSERT(__vectors == __stack_top + 0x200, "the vector table is HW-18's, above the reserved area")
    ASSERT(sb_irq_stubs_end - sb_irq_stubs == 128 * 2, "crt0.S's stubs must be 2 bytes each")

    /* Debug information: kept in the ELF, never loaded. Every section is
     * placed by name (the build links with --orphan-handling=error). */
    .debug_info     0 : { *(.debug_info) }
    .debug_abbrev   0 : { *(.debug_abbrev) }
    .debug_line     0 : { *(.debug_line) }
    .debug_str      0 : { *(.debug_str) }
    .debug_loc      0 : { *(.debug_loc) }
    .debug_ranges   0 : { *(.debug_ranges) }
    .debug_frame    0 : { *(.debug_frame) }
    .debug_macinfo  0 : { *(.debug_macinfo) }
    .debug_pubnames 0 : { *(.debug_pubnames) }
    .debug_pubtypes 0 : { *(.debug_pubtypes) }

    /DISCARD/ : { *(.comment) }
}

