    """True when every word of argv naming path is the value of a
    MESSAGE_FILE_OPTS option."""
    return all(argv[k - 1] in MESSAGE_FILE_OPTS if k else False
               for k, t in enumerate(argv) if path in t)


def access_hits(kind, target, inp, text_hits, written, cwd=""):
    """The access rule's hits for one call: a subset of text_hits (the text
    rule's). `written` maps a file written by a stripped heredoc earlier in
    the session to the hits its body had; a later command using that file
    other than as a message file brings them back."""
    if not text_hits and not (kind == "shell" and any(p in target for p in written)):
        return []
    if kind == "search" and inp.get("pattern") is not None and "path" in inp or \
            kind == "search" and inp.get("pattern") is not None and "glob" in inp:
        # The Grep tool: its pattern is text when it searches our own files.
        path = str(inp.get("path") or "")
        if cwd and (path == cwd or path.startswith(cwd + "/")):
