"""Terms new in #53 (its diff against main, its commit messages, its PR
body) that main, the SDK, the clean baseline and the doors don't have:
the only words C-SEP-TERMS could have hit in #53. Prints each with the
check's hash prefix and where it is."""
import importlib.util, os, subprocess, sys

spec = importlib.util.spec_from_file_location("cet", "tools/check-emulator-terms.py")
cet = importlib.util.module_from_spec(spec); spec.loader.exec_module(cet)
env = dict(os.environ, GIT_NO_LAZY_FETCH="1")

def git(*a):
    p = subprocess.run(["git"] + list(a), stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, env=env)
    return p.stdout.decode("utf-8", "replace") if p.returncode == 0 else None

known = set()
for text in cet.walk_text(cet.SDK):
    sdk = cet.terms_of(text)
    known |= sdk
    known |= set(w for t in sdk if not t.startswith("0x") for w in t.split("_") if cet.shaped(w))
missing = 0
for n in (git("ls-tree", "-r", "--name-only", cet.CLEAN_BASELINE) or "").split():
    t = git("show", "%s:%s" % (cet.CLEAN_BASELINE, n))
    if t is None:
        missing += 1
    else:
        known |= cet.terms_of(t)
known |= cet.door_terms("main")
for n in (git("ls-tree", "-r", "--name-only", "main") or "").split():
    if n.startswith(cet.EXCLUDE):
        continue
    t = git("show", "main:" + n)
    if t:
        known |= cet.terms_of(t)
new = {}
for n in (git("diff", "--name-only", "main", "m4/firmware") or "").split():
    if n.startswith(cet.EXCLUDE):
        continue
    t = git("show", "m4/firmware:" + n)
    if t:
        for i, line in enumerate(t.splitlines(), 1):
            for term in cet.terms_of(line) - known:
                new.setdefault(term, []).append("%s:%d" % (n, i))
msgs = git("log", "--format=%B", "main..m4/firmware") or ""
for term in cet.terms_of(msgs) - known:
    new.setdefault(term, []).append("commit messages")
body = open(sys.argv[1]).read() if len(sys.argv) > 1 else ""
for term in cet.terms_of(body) - known:
    new.setdefault(term, []).append("PR body")
print("baseline blobs not here: %d" % missing)
for term in sorted(new, key=lambda t: cet.h(t)):
    print(cet.h(term), term, ", ".join(new[term][:3]), "(%d places)" % len(new[term]))
